[CmdletBinding()]
param([Parameter(Mandatory = $true)][string]$SimulatorExecPath)
$ErrorActionPreference='Stop'; $ProjectRoot=Split-Path -Parent $PSScriptRoot; $RunId=Get-Date -Format 'yyyyMMdd-HHmmss'
$RunRoot=Join-Path $ProjectRoot (Join-Path 'build' (Join-Path 'm3b-ov5640-cdc-staging' $RunId)); $WorkLib=Join-Path $RunRoot 'work'; $LogPath=Join-Path $RunRoot 'run.log'
function Require-Executable { param([string]$Name); $Path=Join-Path $SimulatorExecPath $Name; if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){throw "Required simulator executable not found: $Path"}; return $Path }
New-Item -ItemType Directory -Force -Path $RunRoot | Out-Null; $Vlib=Require-Executable 'vlib.exe'; $Vlog=Require-Executable 'vlog.exe'; $Vmap=Require-Executable 'vmap.exe'; $Vsim=Require-Executable 'vsim.exe'; Push-Location $RunRoot
try { & $Vlib $WorkLib 2>&1|Tee-Object $LogPath; if($LASTEXITCODE-ne 0){throw 'vlib.exe failed'}; $Sources=@((Join-Path $ProjectRoot 'rtl\ov5640_dvp_rgb565_capture.sv'),(Join-Path $ProjectRoot 'rtl\rgb565_grayscale.sv'),(Join-Path $ProjectRoot 'rtl\ov5640_dvp_rgb565_pipeline.sv'),(Join-Path $ProjectRoot 'rtl\rgb565_word_packer.sv'),(Join-Path $ProjectRoot 'rtl\ov5640_dvp_rgb565_word_pipeline.sv'),(Join-Path $ProjectRoot 'rtl\rgb565_word_to_axis4_adapter.sv'),(Join-Path $ProjectRoot 'rtl\rgb565_axis4_async_fifo.sv'),(Join-Path $ProjectRoot 'rtl\rgb565_axis4_cdc_bridge.sv'),(Join-Path $ProjectRoot 'rtl\ov5640_dvp_rgb565_cdc_staging_pipeline.sv'),(Join-Path $ProjectRoot 'tb\tb_ov5640_dvp_rgb565_cdc_staging_pipeline.sv')); & $Vlog -sv -work $WorkLib $Sources 2>&1|Tee-Object $LogPath -Append; if($LASTEXITCODE-ne 0){throw 'vlog.exe failed'}; & $Vmap work $WorkLib 2>&1|Tee-Object $LogPath -Append; if($LASTEXITCODE-ne 0){throw 'vmap.exe failed'}; & $Vsim -c -lib work tb_ov5640_dvp_rgb565_cdc_staging_pipeline -do 'run -all; quit -f' 2>&1|Tee-Object $LogPath -Append; if($LASTEXITCODE-ne 0){exit $LASTEXITCODE}; if(@(Select-String -LiteralPath $LogPath -Pattern '^(?:# )?TEST PASS$').Count-ne 1){throw 'Expected exactly one TEST PASS marker'}; Write-Output "M3-B OV5640 CDC staging PASS: $LogPath" } finally { Pop-Location }
